    // Iterate over the array and calculate the sum of each pair
    for (int i = 0; i < arr.length - 1; i += 2) {
        int pairSum = arr[i] + arr[i + 1];
        if (pairSums.containsKey(pairSum)) {
            pairSums.put(pairSum, pairSums.get(pairSum) + 1);
        } else {
            pairSums.put(pairSum, 1);
